-- Original syllabus-linked question pool for personalised Sunday diagnostics.
-- Apply only after the PYQ API filter migration is deployed; these are NOT previous-year questions.
with q(exam_slug,node_id,body,options,correct_option,explanation,difficulty) as (values
('neet-ug','1b60a244-3204-4522-b9e3-3585527d7c49',$q$For a hydrogen atom, what is the energy of the n = 2 Bohr orbit?$q$,jsonb_build_array('−13.6 eV','−6.8 eV','−3.4 eV','−1.51 eV'),2,$q$E_n = −13.6/n² eV for hydrogen. At n=2, E = −3.4 eV.$q$,'medium'),
('neet-ug','1b60a244-3204-4522-b9e3-3585527d7c49',$q$How many orbitals are present in a p subshell?$q$,jsonb_build_array('1','3','5','7'),1,$q$For l=1, the number of orbitals is 2l+1 = 3.$q$,'easy'),
('neet-ug','1b60a244-3204-4522-b9e3-3585527d7c49',$q$What is the maximum number of electrons in the shell with principal quantum number n=3?$q$,jsonb_build_array('8','18','32','9'),1,$q$Maximum electrons in a shell = 2n². For n=3, this is 18.$q$,'easy'),
('neet-ug','1b60a244-3204-4522-b9e3-3585527d7c49',$q$When an electron in a hydrogen atom moves from n=3 to n=2, the atom:$q$,jsonb_build_array('Absorbs a photon','Emits a photon','Loses a proton','Becomes ionised'),1,$q$The transition releases the energy difference as a photon.$q$,'medium'),
('neet-ug','1b60a244-3204-4522-b9e3-3585527d7c49',$q$For a hydrogen-like species, the Bohr energy magnitude at a fixed n is proportional to:$q$,jsonb_build_array('Z','Z²','1/Z','1/Z²'),1,$q$For a hydrogen-like ion, E_n = −13.6 Z²/n² eV.$q$,'medium'),
('bihar-police','938d8c7c-7d1c-4a8a-954c-ba7616fe0f7c',$q$In which year did the Champaran Satyagraha take place?$q$,jsonb_build_array('1905','1917','1920','1942'),1,$q$The Champaran Satyagraha took place in 1917.$q$,'easy'),
('bihar-police','938d8c7c-7d1c-4a8a-954c-ba7616fe0f7c',$q$The tinkathia system in Champaran was associated with the forced cultivation of:$q$,jsonb_build_array('Tea','Indigo','Jute','Cotton'),1,$q$Cultivators were compelled to grow indigo on a portion of their land.$q$,'medium'),
('bihar-police','938d8c7c-7d1c-4a8a-954c-ba7616fe0f7c',$q$Which method was central to Gandhi’s approach in Champaran?$q$,jsonb_build_array('Armed revolt','Satyagraha and non-violent resistance','Boycott of all schools','Military action'),1,$q$Gandhi used satyagraha, local enquiry and non-violent resistance.$q$,'easy'),
('bihar-police','938d8c7c-7d1c-4a8a-954c-ba7616fe0f7c',$q$The Quit India Movement was launched in which year?$q$,jsonb_build_array('1930','1935','1942','1946'),2,$q$The Quit India Movement began in August 1942.$q$,'easy'),
('bihar-police','938d8c7c-7d1c-4a8a-954c-ba7616fe0f7c',$q$The slogan “Do or Die” is associated with which movement?$q$,jsonb_build_array('Non-Cooperation Movement','Civil Disobedience Movement','Quit India Movement','Swadeshi Movement'),2,$q$Gandhi gave the “Do or Die” call during the Quit India Movement in 1942.$q$,'easy'),
('bpsc','8298a386-1cb6-4ba0-b7df-1f75319a818c',$q$Fundamental Rights are primarily contained in which part of the Constitution?$q$,jsonb_build_array('Part II','Part III','Part IV','Part IVA'),1,$q$Part III, Articles 12–35, contains the Fundamental Rights.$q$,'easy'),
('bpsc','8298a386-1cb6-4ba0-b7df-1f75319a818c',$q$Which Article provides the right to move the Supreme Court for enforcement of Fundamental Rights?$q$,jsonb_build_array('Article 14','Article 19','Article 21','Article 32'),3,$q$Article 32 guarantees the right to constitutional remedies before the Supreme Court.$q$,'easy'),
('bpsc','8298a386-1cb6-4ba0-b7df-1f75319a818c',$q$Directive Principles of State Policy are contained in:$q$,jsonb_build_array('Part III','Part IV','Part IVA','Part V'),1,$q$DPSPs are contained in Part IV, Articles 36–51.$q$,'easy'),
('bpsc','8298a386-1cb6-4ba0-b7df-1f75319a818c',$q$Fundamental Duties are listed under which Article?$q$,jsonb_build_array('Article 32','Article 44','Article 51A','Article 368'),2,$q$Article 51A in Part IVA lists the Fundamental Duties.$q$,'easy'),
('bpsc','8298a386-1cb6-4ba0-b7df-1f75319a818c',$q$Which Article gives High Courts power to issue writs for Fundamental Rights and other legal purposes?$q$,jsonb_build_array('Article 32','Article 136','Article 226','Article 280'),2,$q$Article 226 gives High Courts writ jurisdiction beyond Fundamental Rights.$q$,'medium'),
('cds','a9e5c9a2-9652-4ae1-a399-a7e0ae2fc36b',$q$A total of 40 is divided in the ratio 3:5. What is the larger share?$q$,jsonb_build_array('15','20','25','30'),2,$q$Total parts = 8; one part = 5. Larger share = 25.$q$,'easy'),
('cds','a9e5c9a2-9652-4ae1-a399-a7e0ae2fc36b',$q$If a:b = 4:7 and b = 35, what is a?$q$,jsonb_build_array('15','20','25','28'),1,$q$Seven parts equal 35, so one part is 5 and a = 20.$q$,'easy'),
('cds','a9e5c9a2-9652-4ae1-a399-a7e0ae2fc36b',$q$What is 20% of 250?$q$,jsonb_build_array('25','40','50','60'),2,$q$20% of 250 = 50.$q$,'easy'),
('cds','a9e5c9a2-9652-4ae1-a399-a7e0ae2fc36b',$q$The average of 6, 8, 10 and 12 is:$q$,jsonb_build_array('8','9','10','11'),1,$q$Average = 36/4 = 9.$q$,'easy'),
('cds','a9e5c9a2-9652-4ae1-a399-a7e0ae2fc36b',$q$A value increases by 10% and then decreases by 10%. The net change is:$q$,jsonb_build_array('No change','1% increase','1% decrease','2% decrease'),2,$q$1.10×0.90 = 0.99, a 1% decrease.$q$,'medium'),
('cuet-ug','0b2d78b3-2c95-4284-91b4-4baba051048d',$q$The Constitution of India was adopted by the Constituent Assembly on:$q$,jsonb_build_array('15 August 1947','26 November 1949','26 January 1950','2 October 1950'),1,$q$The Constitution was adopted on 26 November 1949 and came into effect on 26 January 1950.$q$,'easy'),
('cuet-ug','0b2d78b3-2c95-4284-91b4-4baba051048d',$q$Which set of ideals is expressly stated in the Preamble?$q$,jsonb_build_array('Justice, liberty, equality and fraternity','Profit, growth, security and trade','Monarchy, privilege, rank and status','War, power, territory and conquest'),0,$q$The Preamble sets out justice, liberty, equality and fraternity.$q$,'easy'),
('cuet-ug','0b2d78b3-2c95-4284-91b4-4baba051048d',$q$Which institution is primarily responsible for interpreting the Constitution and adjudicating disputes?$q$,jsonb_build_array('Legislature','Executive','Judiciary','Election Commission'),2,$q$The judiciary interprets the Constitution and adjudicates legal disputes.$q$,'medium'),
('cuet-ug','0b2d78b3-2c95-4284-91b4-4baba051048d',$q$The Union Council of Ministers is collectively responsible to the:$q$,jsonb_build_array('Rajya Sabha','Lok Sabha','Supreme Court','Election Commission'),1,$q$Collective responsibility to the Lok Sabha is a defining feature of parliamentary government.$q$,'easy'),
('cuet-ug','0b2d78b3-2c95-4284-91b4-4baba051048d',$q$Federalism in India primarily refers to:$q$,jsonb_build_array('Division of powers between Union and States','Rule by the armed forces','Abolition of State governments','Direct rule by courts'),0,$q$Federalism divides powers between Union and State governments.$q$,'easy'),
('ibps-sbi-banking','f9a6e39c-69d4-42f3-b9fe-bfd35bd5f6bb',$q$A price rises by 10% and then falls by 10%. What is the net percentage change?$q$,jsonb_build_array('No change','1% increase','1% decrease','2% decrease'),2,$q$The combined multiplier is 1.10×0.90 = 0.99, a net decrease of 1%.$q$,'medium'),
('ibps-sbi-banking','f9a6e39c-69d4-42f3-b9fe-bfd35bd5f6bb',$q$A population of 1,000 grows by 10% per year. What is the population after two years?$q$,jsonb_build_array('1,100','1,200','1,210','1,220'),2,$q$1000×1.1² = 1,210.$q$,'medium'),
('ibps-sbi-banking','f9a6e39c-69d4-42f3-b9fe-bfd35bd5f6bb',$q$A quantity is reduced by 20%. What multiplier gives the new value as a fraction of the original?$q$,jsonb_build_array('0.2','0.8','1.2','1.8'),1,$q$After a 20% reduction, 80% remains, so the multiplier is 0.8.$q$,'easy'),
('ibps-sbi-banking','f9a6e39c-69d4-42f3-b9fe-bfd35bd5f6bb',$q$A value increases by 20% and then decreases by 10%. What is the net change?$q$,jsonb_build_array('8% increase','10% increase','12% increase','2% decrease'),0,$q$1.20×0.90 = 1.08, an 8% increase.$q$,'medium'),
('ibps-sbi-banking','f9a6e39c-69d4-42f3-b9fe-bfd35bd5f6bb',$q$When two percentage changes occur successively, the second percentage is calculated on:$q$,jsonb_build_array('Always the original value','The value after the first change','The average of both values','The difference between the rates'),1,$q$Each successive percentage is applied to the value after the previous change.$q$,'medium'),
('jee-advanced','57f0798d-8b66-4a1f-805d-a06d89afbe99',$q$A 4 kg body accelerates at 3 m s⁻². What is the net force?$q$,jsonb_build_array('7 N','12 N','16 N','24 N'),1,$q$F = ma = 4×3 = 12 N.$q$,'easy'),
('jee-advanced','57f0798d-8b66-4a1f-805d-a06d89be99',$q$A block has normal reaction 100 N and coefficient of limiting static friction 0.25. The limiting friction is:$q$,jsonb_build_array('15 N','20 N','25 N','40 N'),2,$q$f_s,max = μ_sN = 25 N.$q$,'medium'),
('jee-advanced','57f0798d-8b66-4a1f-805d-a06d89be99',$q$Action and reaction forces in Newton’s third law act on:$q$,jsonb_build_array('The same body','Different bodies','Only bodies at rest','Only bodies with equal masses'),1,$q$Action and reaction act on two different interacting bodies.$q$,'easy'),
('jee-advanced','57f0798d-8b66-4a1f-805d-a06d89be99',$q$If the required friction is 8 N and the limiting static friction is 20 N, the actual static friction is:$q$,jsonb_build_array('0 N','8 N','20 N','28 N'),1,$q$Static friction adjusts to the required value up to its limiting value.$q$,'medium'),
('jee-advanced','57f0798d-8b66-4a1f-805d-a06d89be99',$q$For a block on a frictionless incline of angle θ, the component of gravity along the plane is:$q$,jsonb_build_array('mg cosθ','mg sinθ','mg tanθ','mg'),1,$q$The component parallel to the plane is mg sinθ.$q$,'medium'),
('jee-main','73565882-1274-4ee4-a6e8-5bcea9eb83ed',$q$A net force of 12 N acts on a 3 kg body. Its acceleration is:$q$,jsonb_build_array('2 m s⁻²','3 m s⁻²','4 m s⁻²','6 m s⁻²'),2,$q$a = F/m = 4 m s⁻².$q$,'easy'),
('jee-main','73565882-1274-4ee4-a6e8-5bcea9eb83ed',$q$If the net external force on a body is zero, its acceleration is:$q$,jsonb_build_array('Zero','Always 9.8 m s⁻²','Always increasing','Infinite'),0,$q$Zero resultant force gives zero acceleration for constant mass.$q$,'easy'),
('jee-main','73565882-1274-4ee4-a6e8-5bcea9eb83ed',$q$A free-body diagram should show:$q$,jsonb_build_array('Only forces acting on the selected body','Forces exerted by the selected body on all others','Only action-reaction pairs','Only forces in the direction of motion'),0,$q$A free-body diagram includes all external forces acting on the isolated body.$q$,'medium'),
('jee-main','73565882-1274-4ee4-a6e8-5bcea9eb83ed',$q$Impulse delivered to a body equals its change in:$q$,jsonb_build_array('Kinetic energy','Momentum','Potential energy','Mass'),1,$q$The impulse-momentum theorem states J = Δp.$q$,'medium'),
('jee-main','73565882-1274-4ee4-a6e8-5bcea9eb83ed',$q$Kinetic friction on a sliding block acts:$q$,jsonb_build_array('Along the direction of relative sliding','Opposite the relative sliding direction','Always vertically upward','Always towards the centre of Earth'),1,$q$Kinetic friction opposes relative sliding at the contact surface.$q$,'easy'),
('nda','aaba5f2c-9381-4ea5-b505-e4f020135c4a',$q$The centripetal acceleration of a body moving at speed v in a circle of radius r is:$q$,jsonb_build_array('v/r','v²/r','vr','r/v²'),1,$q$a_c = v²/r, directed towards the centre.$q$,'easy'),
('nda','aaba5f2c-9381-4ea5-b505-e4f020135c4a',$q$If the speed of a body in uniform circular motion doubles while radius is unchanged, centripetal acceleration becomes:$q$,jsonb_build_array('Double','Four times','Half','Unchanged'),1,$q$a_c = v²/r; doubling speed multiplies acceleration by four.$q$,'medium'),
('nda','aaba5f2c-9381-4ea5-b505-e4f020135c4a',$q$For a frictionless banked road, the relation between banking angle θ, speed v and radius r is:$q$,jsonb_build_array('tanθ = rg/v²','tanθ = v²/(rg)','sinθ = v/r','cosθ = v²/(rg)'),1,$q$For ideal banking without friction, tanθ = v²/(rg).$q$,'medium'),
('nda','aaba5f2c-9381-4ea5-b505-e4f020135c4a',$q$For constant mass, Newton’s second law is written as:$q$,jsonb_build_array('F = mv','F = ma','F = m/a','F = a/m'),1,$q$For constant mass, resultant force equals mass times acceleration.$q$,'easy'),
('nda','aaba5f2c-9381-4ea1-a505-e4f020135c4a',$q$Static friction can take a value:$q$,jsonb_build_array('Only μsN','Between zero and μsN','Always greater than μsN','Only μkN'),1,$q$Static friction adjusts from zero up to its limiting value μsN.$q$,'medium'),
('rrb-ntpc','cbcab941-2d9b-4cc7-b973-f0f54955f672',$q$A train covers 180 km in 3 hours. Its average speed is:$q$,jsonb_build_array('45 km/h','50 km/h','60 km/h','90 km/h'),2,$q$Speed = 180/3 = 60 km/h.$q$,'easy'),
('rrb-ntpc','cbcab941-2d9b-4cc7-b973-f0f54955f672',$q$A 120 m train crosses a 180 m platform at 15 m/s. How long does it take?$q$,jsonb_build_array('8 s','12 s','20 s','24 s'),2,$q$Distance = 120+180 = 300 m; time = 300/15 = 20 s.$q$,'medium'),
('rrb-ntpc','cbcab941-2d9b-4cc7-b973-f0f54955f672',$q$Two trains move in opposite directions at 40 km/h and 50 km/h. Their relative speed is:$q$,jsonb_build_array('10 km/h','45 km/h','90 km/h','2,000 km/h'),2,$q$For opposite directions, relative speeds add: 90 km/h.$q$,'easy'),
('rrb-ntpc','cbcab941-2d9b-4cc7-b973-f0f54955f672',$q$If a worker completes a job in 8 days at a constant rate, the worker’s one-day work is:$q$,jsonb_build_array('1/4','1/6','1/8','8'),2,$q$One-day work is 1/8 of the job.$q$,'easy'),
('rrb-ntpc','cbcab941-2d9b-4cc7-b973-f0f54955f672',$q$Convert 72 km/h into m/s.$q$,jsonb_build_array('10 m/s','15 m/s','20 m/s','25 m/s'),2,$q$72×5/18 = 20 m/s.$q$,'easy'),
('ssc-cgl','505a54b7-c5e6-47a1-92d6-4dbbfdbf638d',$q$Fundamental Rights are contained in:$q$,jsonb_build_array('Part II','Part III','Part IV','Part IVA'),1,$q$Fundamental Rights are contained in Part III.$q$,'easy'),
('ssc-cgl','505a54b7-c5e6-47a1-92d6-4dbbfdbf638d',$q$Which Article is associated with constitutional remedies for Fundamental Rights?$q$,jsonb_build_array('Article 14','Article 21','Article 32','Article 51A'),2,$q$Article 32 provides the right to move the Supreme Court for enforcement of Fundamental Rights.$q$,'easy'),
('ssc-cgl','505a54b7-c5e6-47a1-92d6-4dbbfdbf638d',$q$Fundamental Duties are listed in:$q$,jsonb_build_array('Article 19','Article 32','Article 44','Article 51A'),3,$q$Article 51A lists Fundamental Duties.$q$,'easy'),
('ssc-cgl','505a54b7-c5e6-47a1-92d6-4dbbfdbf638d',$q$Directive Principles of State Policy are generally:$q$,jsonb_build_array('Directly enforceable by courts','Non-justiciable guiding principles','Private contractual rights','Criminal offences'),1,$q$DPSPs guide policy but are not directly enforceable by courts.$q$,'medium'),
('ssc-cgl','505a54b7-c5e6-47a1-92d6-4dbbfdbf638d',$q$Which Article empowers High Courts to issue writs?$q$,jsonb_build_array('Article 32','Article 136','Article 226','Article 280'),2,$q$Article 226 gives High Courts writ jurisdiction.$q$,'medium'),
('upsc-cse','681fcd59-c401-4fd4-ae70-09d338501341',$q$The Preamble to the Constitution of India is:$q$,jsonb_build_array('Not part of the Constitution','Part of the Constitution','An ordinary statute','A schedule'),1,$q$The Supreme Court has held that the Preamble is part of the Constitution.$q$,'medium'),
('upsc-cse','681fcd59-c401-4fd4-ae70-09d338501341',$q$Which Article empowers the Supreme Court to issue writs for enforcement of Fundamental Rights?$q$,jsonb_build_array('Article 14','Article 19','Article 32','Article 226'),2,$q$Article 32 provides Supreme Court writ jurisdiction for Fundamental Rights.$q$,'easy'),
('upsc-cse','681fcd59-c401-4fd4-ae70-09d338501341',$q$Which of the following is NOT one of the five traditional writs?$q$,jsonb_build_array('Habeas corpus','Mandamus','Certiorari','Referendum'),3,$q$The five writs are habeas corpus, mandamus, prohibition, certiorari and quo warranto.$q$,'medium'),
('upsc-cse','681fcd59-c401-4fd4-ae70-09d338501341',$q$Compared with Article 32, Article 226 gives High Courts writ jurisdiction for:$q$,jsonb_build_array('Only criminal appeals','Fundamental Rights and other legal purposes','Only tax disputes','Only election petitions'),1,$q$Article 226 covers Fundamental Rights and other legal purposes.$q$,'medium'),
('upsc-cse','681fcd59-c401-4fd4-ae70-09d338501341',$q$Fundamental Duties are found in:$q$,jsonb_build_array('Part III','Part IV','Part IVA','Part V'),2,$q$Fundamental Duties are in Part IVA under Article 51A.$q$,'easy')
)
insert into public.questions(exam_id,node_id,mock_test_id,body,options,correct_option,explanation,difficulty,source,is_pyq)
select e.id,q.node_id::uuid,null,q.body,q.options,q.correct_option,q.explanation,q.difficulty,'PrepX Ai original syllabus-linked question pool',false
from q join public.exams e on e.slug=q.exam_slug
where not exists (
  select 1 from public.questions existing
  where existing.exam_id=e.id and existing.node_id=q.node_id::uuid and existing.body=q.body
);
